// `comment edit` and `comment delete` (docs/specs/015-api/cli.md "Commands"; agent-presence "Comments"): the CLI's
// twins of change_threads' edit and delete, over the same shared run (../mcp/thread-run), so a canvas product's CLI
// changes the token's own comments as its MCP does. A thread is named by its element's ref and a comment by its id or
// a prefix (`comment ls` prints the first eight characters and marks an agent's [AI]). The api stamps every comment
// a token writes Generated by AI and refuses a token's edit or delete of a person's comment; the run refuses it
// first, in words.

import { z } from 'zod';
import type { ApiClient } from '@liveworkspace/api-client';
import { defineVerb, VerbRefusal } from '../define';
import { createThreadRun, type ThreadChange } from '../mcp/thread-run';
import type { AgentProduct } from '../product';

export type CommentChangeVerbsBinding = {
  product: AgentProduct;
  // The input key the file's positional takes (`doc`), as the product's other comment verbs name it.
  arg: string;
  // The product's addressing (../addressing `resolveFile`): a name, id prefix or link of a live file.
  resolveFile: (
    api: ApiClient,
    input: string,
    host: string,
    log: (line: string) => void,
  ) => Promise<{ id: string; name: string }>;
};

// The run's refusals that name something missing, answered 404 as the other comment verbs' are; the rest are 403
// (a person's comment) or 409 (the api's own words).
const NOT_FOUND = new Set([
  'no_thread',
  'comment_unknown',
  'comment_ambiguous',
  'ref_ambiguous',
  'tab_unknown',
]);
const FORBIDDEN = new Set(['not_ai_comment']);

const lineOutput = z.object({ text: z.string(), id: z.string() });
const lineText = ({ text }: { text: string }) => [text];
const quietId = ({ id }: { id: string }) => [id];

export function createCommentChangeVerbs({ product, arg, resolveFile }: CommentChangeVerbsBinding) {
  const { cli } = product;
  const { applyThreadChanges } = createThreadRun(product);
  const fileArg = z.string().describe(`A name, id prefix or ${cli} URL`);
  const tabFlag = z
    .string()
    .optional()
    .describe('A tab name or id; any tab when the ref names one thread');
  const refArg = z.string().describe('The element’s ref, from a view');
  const commentArg = z
    .string()
    .min(1)
    .describe('The comment’s id, or a prefix of it (four characters or more), from comment ls');

  // One change, applied; a refusal (the run's, or the api's in words) becomes the verb's.
  async function changeOne(
    api: ApiClient,
    host: string,
    log: (line: string) => void,
    file: string,
    change: ThreadChange,
  ): Promise<{ id: string; text: string }> {
    const { id } = await resolveFile(api, file, host, log);
    const { applied, refusal } = await applyThreadChanges(api, id, [change], () => null);
    if (refusal)
      throw new VerbRefusal({
        status: NOT_FOUND.has(refusal.code) ? 404 : FORBIDDEN.has(refusal.code) ? 403 : 409,
        code: refusal.code,
        message: refusal.message,
        hint: `the comments and their ids are in: ${cli} comment ls ${JSON.stringify(file)} --status all`,
      });
    // One change asked, none refused: one applied, `~ comment <id> on <ref>` or `- comment <id> from <ref>`.
    const line = applied[0]!;
    return { id: line.split(' ')[2]!, text: line };
  }

  const fileOf = (input: Record<string, unknown>) => input[arg] as string;

  const commentEdit = defineVerb({
    id: 'comment.edit',
    summary: 'Edit a comment the agent wrote',
    description:
      'Replaces the text of a comment an agent wrote (marked [AI] in comment ls) and marks it edited; a person’s comment is refused.',
    behaviour: 'write',
    input: z.object({
      [arg]: fileArg,
      tab: tabFlag,
      ref: refArg,
      comment: commentArg,
      text: z.string().min(1).describe('The comment’s new text'),
    }),
    output: lineOutput,
    run: async (ctx, input) => {
      const { tab, ref, comment, text } = input as {
        tab?: string;
        ref: string;
        comment: string;
        text: string;
      };
      return changeOne(ctx.api, ctx.host, ctx.log, fileOf(input), {
        op: 'edit',
        ref,
        comment,
        text,
        ...(tab !== undefined ? { tabId: tab } : {}),
      });
    },
    text: lineText,
    quiet: quietId,
    cli: {
      positionals: [arg, 'ref', 'comment', 'text'],
      examples: [
        `${cli} comment edit "Shop" api 3f9c1a2b "Yes, keyed by order id"`,
        `${cli} comment edit 3f9c --tab Flow 146b c1f0 "Retry twice, then stop"`,
      ],
      prints: '~ comment <id> on <ref>',
    },
  });

  const commentDelete = defineVerb({
    id: 'comment.delete',
    summary: 'Delete a comment the agent wrote',
    description:
      'Deletes a comment an agent wrote (marked [AI] in comment ls); a person’s comment is refused. Deleting a thread’s last comment deletes the thread.',
    behaviour: 'destructive',
    input: z.object({ [arg]: fileArg, tab: tabFlag, ref: refArg, comment: commentArg }),
    output: lineOutput,
    run: async (ctx, input) => {
      const { tab, ref, comment } = input as { tab?: string; ref: string; comment: string };
      return changeOne(ctx.api, ctx.host, ctx.log, fileOf(input), {
        op: 'delete',
        ref,
        comment,
        ...(tab !== undefined ? { tabId: tab } : {}),
      });
    },
    text: lineText,
    quiet: quietId,
    cli: {
      positionals: [arg, 'ref', 'comment'],
      examples: [
        `${cli} comment delete "Shop" api 3f9c1a2b`,
        `${cli} comment delete 3f9c --tab Flow 146b c1f0`,
      ],
      prints: '- comment <id> from <ref>',
    },
  });

  return { commentEdit, commentDelete };
}
